function.arguments:
{"command": "cat <<'EOF' > src/main.rs
use std::collections::HashMap;
use std::env;
use std::fs::{self, File};
use std::io::{self, BufRead, BufReader, Read, Write};
use std::path::{Path, PathBuf};
use std::process;

const VERSION: &str = "0.9.9";
const DEFAULT_MAXAGE: u64 = 10000;

fn main() {
    let args: Vec<String> = env::args().collect();

    if args.len() > 1 && (args[1] == "--help" || args[1] == "-h") {
        print_help();
        process::exit(0);
    }

    if args.len() > 1 && (args[1] == "--version" || args[1] == "-V") {
        println!("zoxide {}", VERSION);
        process::exit(0);
    }

    let command = if args.len() > 1 {
        &args[1]
    } else {
        print_help();
        process::exit(0);
    };

    match command.as_str() {
        "add" => run_add(&args[2..]),
        "edit" => run_edit(),
        "import" => run_import(&args[2..]),
        "init" => run_init(&args[2..]),
        "query" => run_query(&args[2..]),
        "remove" => run_remove(&args[2..]),
        _ => {
            eprintln!("zoxide: invalid command '{}'", command);
            print_help();
            process::exit(1);
        }
    }
}

fn print_help() {
    println!("zoxide {}", VERSION);
    println!("Ajeet D'Souza <98ajeet@gmail.com>");
    println!("https://github.com/ajeetdsouza/zoxide");
    println!();
    println!("A smarter cd command for your terminal");
    println!();
    println!("Usage:");
    println!("  executable <COMMAND>");
    println!();
    println!("Commands:");
    println!("  add     Add a new directory or increment its rank");
    println!("  edit    Edit the database");
    println!("  import  Import entries from another application");
    println!("  init    Generate shell configuration");
    println!("  query   Search for a directory in the database");
    println!("  remove  Remove a directory from the database");
    println!();
    println!("Options:");
    println!("  -h, --help     Print help");
    println!("  -V, --version  Print version");
    println!();
    println!("Environment variables:");
    println!("  _ZO_DATA_DIR          Path for zoxide data files");
    println!("  _ZO_ECHO              Print the matched directory before navigating to it when set to 1");
    println!("  _ZO_EXCLUDE_DIRS      List of directory globs to be excluded");
    println!("  _ZO_FZF_OPTS          Custom flags to pass to fzf");
    println!("  _ZO_MAXAGE            Maximum total age after which entries start getting deleted");
    println!("  _ZO_RESOLVE_SYMLINKS  Resolve symlinks when storing paths");
}

fn get_data_dir() -> PathBuf {
    if let Some(dir) = env::var_os("_ZO_DATA_DIR") {
        PathBuf::from(dir)
    } else {
        // Default to XDG_DATA_HOME or ~/.local/share
        if let Some(home) = home::home_dir() {
            home.join(".local/share")
        } else {
            PathBuf::from(".")
        }
    }
}

fn get_db_path() -> PathBuf {
    get_data_dir().join("db.zo")
}

fn read_db() -> io::Result<HashMap<String, u64>> {
    let db_path = get_db_path();
    if !db_path.exists() {
        return Ok(HashMap::new());
    }

    let file = File::open(&db_path)?;
    let reader = BufReader::new(file);

    let mut db = HashMap::new();
    for line in reader.lines() {
        let line = line?;
        let parts: Vec<&str> = line.split_whitespace().collect();
        if parts.len() >= 2 {
            if let Ok(score) = parts[1].parse::<u64>() {
                db.insert(parts[0].to_string(), score);
            }
        }
    }

    Ok(db)
}

fn write_db(db: &HashMap<String, u64>) -> io::Result<()> {
    let db_path = get_db_path();
    let parent = db_path.parent().unwrap();
    fs::create_dir_all(parent)?;

    let mut file = File::create(&db_path)?;
    for (path, score) in db {
        writeln!(file, "{} {}", path, score)?;
    }
    Ok(())
}

fn run_add(args: &[String]) {
    let mut paths: Vec<String> = args.iter().map(|s| s.clone()).collect();

    let score = if let Some(score_str) = args.iter().find(|s| s == "--score" || s == "-s") {
        let idx = args.iter().position(|s| s == "--score" || s == "-s").unwrap();
        if idx + 1 < args.len() {
            args[idx + 1].clone()
        } else {
            "1".to_string()
        }
    } else {
        "1".to_string()
    };

    let score: u64 = score.parse().unwrap_or(1);

    let db = read_db().unwrap_or_else(|e| {
        eprintln!("zoxide: failed to read database: {}", e);
        process::exit(1);
    });

    for path in &paths {
        let path = path.trim();
        if path.is_empty() {
            continue;
        }

        // Check if path is excluded
        if is_excluded(path) {
            continue;
        }

        let score = db.entry(path.clone()).or_insert(score);
        *score += 1;
    }

    if let Err(e) = write_db(&db) {
        eprintln!("zoxide: failed to write database: {}", e);
        process::exit(1);
    }
}

fn is_excluded(path: &str) -> bool {
    let exclude_dirs = env::var("_ZO_EXCLUDE_DIRS").unwrap_or_default();
    let home = home::home_dir().map(|h| h.to_string_lossy().to_string()).unwrap_or_default();

    if exclude_dirs.is_empty() {
        return false;
    }

    let path = path.to_string();
    let mut parts = path.split('/');

    while let Some(part) = parts.next() {
        if part.is_empty() {
            continue;
        }

        for pattern in exclude_dirs.split(':') {
            if pattern.is_empty() {
                continue;
            }

            let pattern = pattern.trim();
            if pattern.is_empty() {
                continue;
            }

            if pattern == "*" || pattern == "*" || pattern == "*" {
                return true;
            }

            if pattern.starts_with('*') {
                let prefix = &pattern[1..];
                if path.starts_with(prefix) {
                    return true;
                }
            }

            if pattern.ends_with('*') {
                let suffix = &pattern[..pattern.len()-1];
                if path.ends_with(suffix) {
                    return true;
                }
            }

            if path == pattern {
                return true;
            }
        }
    }

    false
}

fn run_edit() {
    let db_path = get_db_path();
    if !db_path.exists() {
        eprintln!("zoxide: database not found");
        process::exit(1);
    }

    let file = File::open(&db_path).unwrap_or_else(|e| {
        eprintln!("zoxide: failed to open database: {}", e);
        process::exit(1);
    });

    let reader = BufReader::new(file);
    for line in reader.lines() {
        println!("{}", line.unwrap());
    }
}

fn run_import(args: &[String]) {
    let mut from = None;
    let mut path = None;
    let mut merge = false;

    for arg in args {
        if arg == "--from" {
            if let Some(idx) = args.iter().position(|s| s == "--from") {
                if idx + 1 < args.len() {
                    from = Some(args[idx + 1].clone());
                }
            }
        } else if arg == "--merge" {
            merge = true;
        } else if !arg.starts_with('-') {
            path = Some(arg.clone());
        }
    }

    let from = match from {
        Some(f) => f,
        None => {
            eprintln!("zoxide: --from is required");
            process::exit(1);
        }
    };

    let path = match path {
        Some(p) => p,
        None => {
            eprintln!("zoxide: path is required");
            process::exit(1);
        }
    };

    let db_path = get_db_path();

    if !Path::new(&path).exists() {
        eprintln!("zoxide: could not open database for importing: {}", path);
        process::exit(1);
    }

    let mut db = read_db().unwrap_or_else(|e| {
        eprintln!("zoxide: failed to read database: {}", e);
        process::exit(1);
    });

    let import_db = match from.as_str() {
        "autojump" => {
            let mut db = HashMap::new();
            if let Ok(file) = File::open(&path) {
                let reader = BufReader::new(file);
                for line in reader.lines() {
                    let line = line.unwrap();
                    let parts: Vec<&str> = line.split_whitespace().collect();
                    if parts.len() >= 2 {
                        if let Ok(score) = parts[1].parse::<u64>() {
                            db.insert(parts[0].to_string(), score);
                        }
                    }
                }
            }
            db
        }
        "z" => {
            let mut db = HashMap::new();
            if let Ok(file) = File::open(&path) {
                let reader = BufReader::new(file);
                for line in reader.lines() {
                    let line = line.unwrap();
                    let parts: Vec<&str> = line.split_whitespace().collect();
                    if parts.len() >= 2 {
                        if let Ok(score) = parts[1].parse::<u64>() {
                            db.insert(parts[0].to_string(), score);
                        }
                    }
                }
            }
            db
        }
        _ => {
            eprintln!("zoxide: unknown import source: {}", from);
            process::exit(1);
        }
    };

    for (path, score) in import_db {
        if merge {
            *db.entry(path).or_insert(0) += score;
        } else {
            db.insert(path, score);
        }
    }

    if let Err(e) = write_db(&db) {
        eprintln!("zoxide: failed to write database: {}", e);
        process::exit(1);
    }
}

fn run_init(args: &[String]) {
    let mut shell = "bash".to_string();
    let mut no_cmd = false;
    let mut cmd = "z".to_string();
    let mut hook = "pwd".to_string();

    for arg in args {
        if arg == "--no-cmd" {
            no_cmd = true;
        } else if arg == "--cmd" {
            if let Some(idx) = args.iter().position(|s| s == "--cmd") {
                if idx + 1 < args.len() {
                    cmd = args[idx + 1].clone();
                }
            }
        } else if arg == "--hook" {
            if let Some(idx) = args.iter().position(|s| s == "--hook") {
                if idx + 1 < args.len() {
                    hook = args[idx + 1].clone();
                }
            }
        } else if !arg.starts_with('-') {
            shell = arg.clone();
        }
    }

    let shells = vec!["bash", "elvish", "fish", "nushell", "posix", "powershell", "tcsh", "xonsh", "zsh"];
    if !shells.contains(&shell.as_str()) {
        eprintln!("zoxide: invalid shell '{}'", shell);
        process::exit(1);
    }

    match shell.as_str() {
        "bash" => init_bash(&no_cmd, &cmd, &hook),
        "elvish" => init_elvish(),
        "fish" => init_fish(),
        "nushell" => init_nushell(),
        "posix" => init_posix(&no_cmd, &cmd, &hook),
        "powershell" => init_powershell(),
        "tcsh" => init_tcsh(),
        "xonsh" => init_xonsh(),
        "zsh" => init_zsh(),
        _ => {
            eprintln!("zoxide: invalid shell '{}'", shell);
            process::exit(1);
        }
    }
}

fn init_bash(no_cmd: bool, cmd: &str, hook: &str) {
    let mut output = String::new();

    output.push_str("# shellcheck shell=bash\n\n");
    output.push_str("# =============================================================================\n#\n");
    output.push_str("# Utility functions for zoxide.\n#\n\n");

    output.push_str("# pwd based on the value of _ZO_RESOLVE_SYMLINKS.\n");
    output.push_str("function __zoxide_pwd() {\n");
    output.push_str("    \\\\builtin pwd -L\n");
    output.push_str("}\n\n");

    output.push_str("# cd + custom logic based on the value of _ZO_ECHO.\n");
    output.push_str("function __zoxide_cd() {\n");
    output.push_str("    # shellcheck disable=SC2164\n");
    output.push_str("    \\\\builtin cd -- \"$@\"\n");
    output.push_str("}\n\n");

    output.push_str("# =============================================================================\n#\n");
    output.push_str("# Hook configuration for zoxide.\n#\n\n");

    if hook == "none" {
        output.push_str("# Report common issues.\n");
        output.push_str("function __zoxide_doctor() {\n");
        output.push_str("    return 0\n");
        output.push_str("}\n\n");
    } else {
        output.push_str("# Hook to add new entries to the database.\n");
        output.push_str("__zoxide_oldpwd=\"$(\\command __zoxide_pwd)\"\n\n");
        output.push_str("function __zoxide_hook() {\n");
        output.push_str("    \\\\builtin local -r retval=\"$?\"\n");
        output.push_str("    \\\\builtin local pwd_tmp\n");
        output.push_str("    pwd_tmp=\"$(\\command __zoxide_pwd)\"\n");
        output.push_str("    if [[ ${__zoxide_oldpwd} != \"${pwd_tmp}\" ]]; then\n");
        output.push_str("        __zoxide_oldpwd=\"${pwd_tmp}\"\n");
        output.push_str("        \\\\command zoxide add -- \"${__zoxide_oldpwd}\"\n");
        output.push_str("    fi\n");
        output.push_str("    return \"${retval}\"\n");
        output.push_str("}\n\n");

        output.push_str("# Initialize hook.\n");
        output.push_str("if [[ ${PROMPT_COMMAND:=} != *\\'__zoxide_hook\\'* ]]; then\n");
        output.push_str("    if [[ \"$(declare -p PROMPT_COMMAND 2\\>\\&1)\" == \"declare -a\"* ]]; then\n");
        output.push_str("        PROMPT_COMMAND=(\"${PROMPT_COMMAND[@]}\" __zoxide_hook)\n");
        output.push_str("    else\n");
        output.push_str("        # shellcheck disable=SC2128,SC2178\n");
        output.push_str("        PROMPT_COMMAND=\"${PROMPT_COMMAND%\"${PROMPT_COMMAND##*[![:space:];]}\"}\"\n");
        output.push_str("        # shellcheck disable=SC2128,SC2178\n");
        output.push_str("        PROMPT_COMMAND=\"${PROMPT_COMMAND:+${PROMPT_COMMAND};}__zoxide_hook\"\n");
        output.push_str("    fi\n");
        output.push_str("fi\n\n");
    }

    output.push_str("# Report common issues.\n");
    output.push_str("function __zoxide_doctor() {\n");
    output.push_str("    [[ ${_ZO_DOCTOR:-1} -eq 0 ]] \\&\\& return 0\n");
    output.push_str("    # shellcheck disable=SC2199\n");
    output.push_str("    [[ ${PROMPT_COMMAND[@]:-} == *\\'__zoxide_hook\\'* ]] \\&\\& return 0\n");
    output.push_str("    # shellcheck disable=SC2199\n");
    output.push_str("    [[ ${__vsc_original_prompt_command[@]:-} == *\\'__zoxide_hook\\'* ]] \\&\\& return 0\n\n");
    output.push_str("    _ZO_DOCTOR=0\n");
    output.push_str("    \\\\builtin printf \\'%s\\n\\' \\\");
    output.push_str("        \\'zoxide: detected a possible configuration issue.\\' \\\");
    output.push_str("        \\'Please ensure that zoxide is initialized right at the end of your shell configuration file (usually ~/.bashrc).\\' \\\");
    output.push_str("        \\'\\' \\\");
    output.push_str("        \\'If the issue persists, consider filing an issue at:\\' \\\");
    output.push_str("        \\'https://github.com/ajeetdsouza/zoxide/issues\\' \\\");
    output.push_str("        \\'\\' \\\");
    output.push_str("        \\'Disable this message by setting _ZO_DOCTOR=0.\\' \\\");
    output.push_str("        \\'\\' \\>\\&2\n");
    output.push_str("}\n\n");

    output.push_str("# =============================================================================\n#\n");
    output.push_str("# When using zoxide with --no-cmd, alias these internal functions as desired.\n#\n\n");

    output.push_str("__zoxide_z_prefix=\\'z#\\'");
    output.push_str("\n\n");

    output.push_str("# Jump to a directory using only keywords.\n");
    output.push_str("function __zoxide_z() {\n");
    output.push_str("    __zoxide_doctor\n\n");
    output.push_str("    # shellcheck disable=SC2199\n");
    output.push_str("    if [[ $# -eq 0 ]]; then\n");
    output.push_str("        __zoxide_cd ~\n");
    output.push_str("    elif [[ $# -eq 1 \\&\\& $1 == \\'-\\' ]]; then\n");
    output.push_str("        __zoxide_cd \"${OLDPWD}\"\n");
    output.push_str("    elif [[ $# -eq 1 \\&\\& -d $1 ]]; then\n");
    output.push_str("        __zoxide_cd \"$1\"\n");
    output.push_str("    elif [[ $# -eq 2 \\&\\& $1 == \\'--\\' ]]; then\n");
    output.push_str("        __zoxide_cd \"$2\"\n");
    output.push_str("    elif [[ ${@: -1} == \"${__zoxide_z_prefix}\"?* ]]; then\n");
    output.push_str("        # shellcheck disable=SC2124\n");
    output.push_str("        \\\\builtin local result=\"${@: -1}\"\n");
    output.push_str("        __zoxide_cd \"${result:${#__zoxide_z_prefix}}\"\n");
    output.push_str("    else\n");
    output.push_str("        \\\\builtin local result\n");
    output.push_str("        # shellcheck disable=SC2312\n");
    output.push_str("        result=\"$(\\command zoxide query --exclude \"$(__zoxide_pwd)\" -- \"$@\")\" \\&\\&\n");
    output.push_str("            __zoxide_cd \"${result}\"\n");
    output.push_str("    fi\n");
