        output.push_str("    [[ :\"${SHELLOPTS}\": =~ :(vi|emacs): \\&\\& ${TERM} != \\'dumb\\' ]]; then\n\n");
        output.push_str("    function __zoxide_z_complete_helper() {\n");
        output.push_str("        READLINE_LINE=\"z ${__zoxide_result@Q}\"\n");
        output.push_str("        READLINE_POINT=${#READLINE_LINE}\n");
        output.push_str("        bind \\'\"\\e[0n\": accept-line\\' \n");
        output.push_str("        \\\\builtin printf \\'\\e[5n\\' \\>\\&/dev/tty\n");
