        output.push_str("    function __zoxide_z_complete() {\n");
        output.push_str("        # Only show completions when the cursor is at the end of the line.\n");
        output.push_str("        [[ ${#COMP_WORDS[@]} -eq $((COMP_CWORD + 1)) ]] || return\n\n");
