}

fn run_import(args: &[String]) {
    let mut from = None;
    let mut path = None;
    let mut merge = false;

    for arg in args {
        if arg == "--from" {
            if let Some(idx) = args.iter().position(|s| s == "--from") {
                if idx + 1 < args.len() {
                    from = Some(args[idx + 1].clone());
