        output.push_str("    if [[ \"$(declare -p PROMPT_COMMAND 2\\>\\&1)\" == \"declare -a\"* ]]; then\n");
        output.push_str("        PROMPT_COMMAND=(\"${PROMPT_COMMAND[@]}\" __zoxide_hook)\n");
        output.push_str("    else\n");
        output.push_str("        # shellcheck disable=SC2128,SC2178\n");
        output.push_str("        PROMPT_COMMAND=\"${PROMPT_COMMAND%\"${PROMPT_COMMAND##*[![:space:];]}\"}\"\n");
        output.push_str("        # shellcheck disable=SC2128,SC2178\n");
        output.push_str("        PROMPT_COMMAND=\"${PROMPT_COMMAND:+${PROMPT_COMMAND};}__zoxide_hook\"\n");
        output.push_str("    fi\n");
        output.push_str("fi\n\n");
    }

    output.push_str("# Report common issues.\n");
    output.push_str("function __zoxide_doctor() {\n");
    output.push_str("    [[ ${_ZO_DOCTOR:-1} -eq 0 ]] \\&\\& return 0\n");
    output.push_str("    # shellcheck disable=SC2199\n");
    output.push_str("    [[ ${PROMPT_COMMAND[@]:-} == *\\'__zoxide_hook\\'* ]] \\&\\& return 0\n");
    output.push_str("    # shellcheck disable=SC2199\n");
    output.push_str("    [[ ${__vsc_original_prompt_command[@]:-} == *\\'__zoxide_hook\\'* ]] \\&\\& return 0\n\n");
    output.push_str("    _ZO_DOCTOR=0\n");
    output.push_str("    \\\\builtin printf \\'%s\\n\\' \\\");
    output.push_str("        \\'zoxide: detected a possible configuration issue.\\' \\\");
    output.push_str("        \\'Please ensure that zoxide is initialized right at the end of your shell configuration file (usually ~/.bashrc).\\' \\\");
    output.push_str("        \\'\\' \\\");
    output.push_str("        \\'If the issue persists, consider filing an issue at:\\' \\\");
    output.push_str("        \\'https://github.com/ajeetdsouza/zoxide/issues\\' \\\");
    output.push_str("        \\'\\' \\\");
    output.push_str("        \\'Disable this message by setting _ZO_DOCTOR=0.\\' \\\");
    output.push_str("        \\'\\' \\>\\&2\n");
    output.push_str("}\n\n");

    output.push_str("# =============================================================================\n#\n");
    output.push_str("# When using zoxide with --no-cmd, alias these internal functions as desired.\n#\n\n");

    output.push_str("__zoxide_z_prefix=\\'z#\\'");
    output.push_str("\n\n");

    output.push_str("# Jump to a directory using only keywords.\n");
    output.push_str("function __zoxide_z() {\n");
    output.push_str("    __zoxide_doctor\n\n");
    output.push_str("    # shellcheck disable=SC2199\n");
    output.push_str("    if [[ $# -eq 0 ]]; then\n");
    output.push_str("        __zoxide_cd ~\n");
    output.push_str("    elif [[ $# -eq 1 \\&\\& $1 == \\'-\\' ]]; then\n");
    output.push_str("        __zoxide_cd \"${OLDPWD}\"\n");
    output.push_str("    elif [[ $# -eq 1 \\&\\& -d $1 ]]; then\n");
    output.push_str("        __zoxide_cd \"$1\"\n");
    output.push_str("    elif [[ $# -eq 2 \\&\\& $1 == \\'--\\' ]]; then\n");
    output.push_str("        __zoxide_cd \"$2\"\n");
    output.push_str("    elif [[ ${@: -1} == \"${__zoxide_z_prefix}\"?* ]]; then\n");
    output.push_str("        # shellcheck disable=SC2124\n");
    output.push_str("        \\\\builtin local result=\"${@: -1}\"\n");
    output.push_str("        __zoxide_cd \"${result:${#__zoxide_z_prefix}}\"\n");
    output.push_str("    else\n");
    output.push_str("        \\\\builtin local result\n");
    output.push_str("        # shellcheck disable=SC2312\n");
    output.push_str("        result=\"$(\\command zoxide query --exclude \"$(__zoxide_pwd)\" -- \"$@\")\" \\&\\&\n");
    output.push_str("            __zoxide_cd \"${result}\"\n");
    output.push_str("    fi\n");
    output.push_str("}\n\n");

    output.push_str("# Jump to a directory using interactive search.\n");
    output.push_str("function __zoxide_zi() {\n");
    output.push_str("    __zoxide_doctor\n");
    output.push_str("    \\\\builtin local result\n");
    output.push_str("    result=\"$(\\command zoxide query --interactive -- \"$@\")\" \\&\\& __zoxide_cd \"${result}\"\n");
    output.push_str("}\n\n");

    output.push_str("# =============================================================================\n#\n");
    output.push_str("# Commands for zoxide. Disable these using --no-cmd.\n#\n\n");

    if no_cmd {
        output.push_str("# -- not configured --\n\n");
    } else {
        output.push_str("\\\\builtin unalias z \\>\\&/dev/null || \\\\builtin true\n");
        output.push_str("function z() {\n");
        output.push_str("    __zoxide_z \"$@\"\n");
        output.push_str("}\n\n");

        output.push_str("\\\\builtin unalias zi \\>\\&/dev/null || \\\\builtin true\n");
        output.push_str("function zi() {\n");
        output.push_str("    __zoxide_zi \"$@\"\n");
        output.push_str("}\n\n");

        output.push_str("# Load completions.\n");
        output.push_str("# - Bash 4.4+ is required to use `@Q`.\n");
        output.push_str("# - Completions require line editing. Since Bash supports only two modes of\n");
        output.push_str("#   line editing (`vim` and `emacs`), we check if either them is enabled.\n");
        output.push_str("# - Completions don\\'t work on `dumb` terminals.\n");
        output.push_str("if [[ ${BASH_VERSINFO[0]:-0} -eq 4 \\&\\& ${BASH_VERSINFO[1]:-0} -ge 4 || ${BASH_VERSINFO[0]:-0} -ge 5 ]] \\&\\&\n");
        output.push_str("    [[ :\"${SHELLOPTS}\": =~ :(vi|emacs): \\&\\& ${TERM} != \\'dumb\\' ]]; then\n\n");
        output.push_str("    function __zoxide_z_complete_helper() {\n");
        output.push_str("        READLINE_LINE=\"z ${__zoxide_result@Q}\"\n");
        output.push_str("        READLINE_POINT=${#READLINE_LINE}\n");
        output.push_str("        bind \\'\"\\e[0n\": accept-line\\' \n");
        output.push_str("        \\\\builtin printf \\'\\e[5n\\' \\>\\&/dev/tty\n");
        output.push_str("    }\n\n");
        output.push_str("    function __zoxide_z_complete() {\n");
        output.push_str("        # Only show completions when the cursor is at the end of the line.\n");
        output.push_str("        [[ ${#COMP_WORDS[@]} -eq $((COMP_CWORD + 1)) ]] || return\n\n");
        output.push_str("        # If there is only one argument, use `cd` completions.\n");
        output.push_str("        if [[ ${#COMP_WORDS[@]} -eq 2 ]]; then\n");
        output.push_str("            \\\\builtin mapfile -t COMPREPLY \\< \\<(\n");
        output.push_str("                \\\\builtin compgen -A directory -- \"${COMP_WORDS[-1]}\" || \\\\builtin true\n");
        output.push_str("            )\n");
        output.push_str("        # If there is a space after the last word, use interactive selection.\n");
        output.push_str("        elif [[ -z ${COMP_WORDS[-1]} ]]; then\n");
        output.push_str("            # shellcheck disable=SC2312\n");
        output.push_str("            __zoxide_result=\"$(\\command zoxide query --exclude \"$(__zoxide_pwd)\" --interactive -- \"${COMP_WORDS[@]:1:${#COMP_WORDS[@]}-2}\")\" \\&\\& {\n");
        output.push_str("                # In case the terminal does not respond to \\e[5n or another\n");
        output.push_str("                # mechanism steals the response, it is still worth completing\n");
        output.push_str("                # the directory in the command line.\n");
        output.push_str("                COMPREPLY=(\"${__zoxide_z_prefix}${__zoxide_result}/\")\n\n");
        output.push_str("                # Note: We here call \"bind\" without prefixing \"\\builtin\" to be\n");
        output.push_str("                # compatible with frameworks like ble.sh, which emulates Bash\\'s\n");
        output.push_str("                # builtin \"bind\".\n");
        output.push_str("                bind -x \\'\"\\e[0n\": __zoxide_z_complete_helper\\' \n");
        output.push_str("                \\\\builtin printf \\'\\e[5n\\' \\>\\&/dev/tty\n");
        output.push_str("            }\n");
        output.push_str("        fi\n");
        output.push_str("    }\n\n");
        output.push_str("    \\\\builtin complete -F __zoxide_z_complete -o filenames -- z\n");
        output.push_str("    \\\\builtin complete -r zi \\>\\&/dev/null || \\\\builtin true\n");
        output.push_str("fi\n\n");
    }

    output.push_str("# =============================================================================\n#\n");
    output.push_str("# To initialize zoxide, add this to your shell configuration file (usually ~/.bashrc):\n#\n");
    output.push_str("# eval \"$(zoxide init bash)\"\n");

    println!("{}", output);
}

