fn init_fish() {
    let mut output = String::new();

    output.push_str("# =============================================================================\n#\n");
    output.push_str("# Utility functions for zoxide.\n#\n\n");

    output.push_str("# pwd based on the value of _ZO_RESOLVE_SYMLINKS.\n");
    output.push_str("function __zoxide_pwd\n");
    output.push_str("    command pwd -L\n");
    output.push_str("end\n\n");

    output.push_str("# cd + custom logic based on the value of _ZO_ECHO.\n");
    output.push_str("function __zoxide_cd\n");
    output.push_str("    command cd -- $argv\n");
    output.push_str("end\n\n");

    output.push_str("# =============================================================================\n#\n");
    output.push_str("# Hook configuration for zoxide.\n#\n\n");

    output.push_str("# Hook to add new entries to the database.\n");
    output.push_str("set -gx __zoxide_oldpwd \"$(command __zoxide_pwd)\"\n\n");
    output.push_str("function __zoxide_hook\n");
    output.push_str("    set -l retval $status\n");
    output.push_str("    set -l pwd_tmp \"$(command __zoxide_pwd)\"\n");
    output.push_str("    if test \"$__zoxide_oldpwd\" != \"$pwd_tmp\"; then\n");
    output.push_str("        set -gx __zoxide_oldpwd \"$pwd_tmp\"\n");
    output.push_str("        command zoxide add -- \"$__zoxide_oldpwd\"\n");
    output.push_str("    end\n");
    output.push_str("    return $retval\n");
    output.push_str("end\n\n");

    output.push_str("# Initialize hook.\n");
    output.push_str("if not contains -- __zoxide_hook $preexec_functions; then\n");
    output.push_str("    set -ga preexec_functions __zoxide_hook\n");
    output.push_str("end\n\n");

    output.push_str("# Report common issues.\n");
    output.push_str("function __zoxide_doctor\n");
    output.push_str("    if test \"$_ZO_DOCTOR\" = \"0\"; then\n");
    output.push_str("        return 0\n");
    output.push_str("    end\n");
    output.push_str("    if contains -- __zoxide_hook $preexec_functions; then\n");
    output.push_str("        return 0\n");
    output.push_str("    end\n");
    output.push_str("    set -gx _ZO_DOCTOR 0\n");
    output.push_str("    printf '%s\\n' \\\");
    output.push_str("        'zoxide: detected a possible configuration issue.' \\\");
    output.push_str("        'Please ensure that zoxide is initialized right at the end of your shell configuration file (usually ~/.config/fish/config.fish).' \\\");
    output.push_str("        '' \\\");
    output.push_str("        'If the issue persists, consider filing an issue at:' \\\");
    output.push_str("        'https://github.com/ajeetdsouza/zoxide/issues' \\\");
    output.push_str("        '' \\\");
    output.push_str("        'Disable this message by setting _ZO_DOCTOR=0.' \\\");
    output.push_str("        '' \\\");
    output.push_str("    | stderr\n");
    output.push_str("end\n\n");

    output.push_str("# =============================================================================\n#\n");
    output.push_str("# When using zoxide with --no-cmd, alias these internal functions as desired.\n#\n\n");

    output.push_str("set -gx __zoxide_z_prefix 'z#'\n\n");

    output.push_str("# Jump to a directory using only keywords.\n");
    output.push_str("function __zoxide_z\n");
    output.push_str("    __zoxide_doctor\n");
    output.push_str("    if test (count $argv) -eq 0; then\n");
    output.push_str("        __zoxide_cd ~\n");
    output.push_str("    elif test (count $argv) -eq 1 -a \"$argv[1]\" = '-'; then\n");
    output.push_str("        __zoxide_cd \"$OLDPWD\"\n");
    output.push_str("    elif test (count $argv) -eq 1 -a -d \"$argv[1]\"; then\n");
    output.push_str("        __zoxide_cd \"$argv[1]\"\n");
    output.push_str("    elif test (count $argv) -eq 2 -a \"$argv[1]\" = '--'; then\n");
    output.push_str("        __zoxide_cd \"$argv[2]\"\n");
    output.push_str("    elif test \"$argv[-1]\" = \"${__zoxide_z_prefix}\"*; then\n");
    output.push_str("        set -l result \"$argv[-1]\"\n");
    output.push_str("        __zoxide_cd \"${result[${#__zoxide_z_prefix}..-1]}\"\n");
    output.push_str("    else\n");
    output.push_str("        set -l result \"$(command zoxide query --exclude \"$(command __zoxide_pwd)\" -- $argv)\"\n");
    output.push_str("        __zoxide_cd \"$result\"\n");
    output.push_str("    end\n");
    output.push_str("end\n\n");

    output.push_str("# Jump to a directory using interactive search.\n");
    output.push_str("function __zoxide_zi\n");
    output.push_str("    __zoxide_doctor\n");
    output.push_str("    set -l result \"$(command zoxide query --interactive -- $argv)\"\n");
    output.push_str("    __zoxide_cd \"$result\"\n");
    output.push_str("end\n\n");

    output.push_str("# =============================================================================\n#\n");
    output.push_str("# Commands for zoxide. Disable these using --no-cmd.\n#\n\n");

    if no_cmd {
        output.push_str("# -- not configured --\n\n");
    } else {
        output.push_str("alias z = '__zoxide_z'\n");
        output.push_str("alias zi = '__zoxide_zi'\n\n");

        output.push_str("# Load completions.\n");
        output.push_str("if command -q fish_complete_zoxide >/dev/null 2>&1; then\n");
        output.push_str("    fish_complete_zoxide\n");
        output.push_str("end\n\n");

        output.push_str("function __zoxide_z_complete\n");
        output.push_str("    set -l result \"$(command zoxide query --exclude \"$(command __zoxide_pwd)\" -- $argv)\"\n");
        output.push_str("    complete -f -c z -a \"$result\"\n");
        output.push_str("end\n\n");
    }

    output.push_str("# =============================================================================\n#\n");
    output.push_str("# To initialize zoxide, add this to your shell configuration file (usually ~/.config/fish/config.fish):\n#\n");
    output.push_str("# eval \"$(zoxide init fish)\"\n");

    println!("{}", output);
}

