    output.push_str("    else {\n");
    output.push_str("        $result = & zoxide query --exclude \"$(__zoxide_pwd)\" -- $args\n");
    output.push_str("        __zoxide_cd $result\n");
    output.push_str("    }\n");
    output.push_str("}\n\n");

    output.push_str("# Jump to a directory using interactive search.\n");
    output.push_str("function __zoxide_zi {\n");
    output.push_str("    __zoxide_doctor\n");
    output.push_str("    $result = & zoxide query --interactive -- $args\n");
