    output.push_str("        __zoxide_cd $result\n");
    output.push_str("    }\n");
    output.push_str("}\n\n");

    output.push_str("# Jump to a directory using interactive search.\n");
    output.push_str("function __zoxide_zi {\n");
    output.push_str("    __zoxide_doctor\n");
    output.push_str("    $result = & zoxide query --interactive -- $args\n");
    output.push_str("    __zoxide_cd $result\n");
    output.push_str("}\n\n");

    output.push_str("# =============================================================================\n#\n");
    output.push_str("# Commands for zoxide. Disable these using --no-cmd.\n#\n\n");

    if no_cmd {
        output.push_str("# -- not configured --\n\n");
    } else {
        output.push_str("Remove-Item -Path function:\\z -ErrorAction SilentlyContinue\n");
        output.push_str("function z {\n");
        output.push_str("    __zoxide_z $args\n");
        output.push_str("}\n\n");

        output.push_str("Remove-Item -Path function:\\zi -ErrorAction SilentlyContinue\n");
        output.push_str("function zi {\n");
        output.push_str("    __zoxide_zi $args\n");
        output.push_str("}\n\n");

        output.push_str("# Load completions.\n");
        output.push_str("if (Get-Command -Name __zoxide_z_complete -ErrorAction SilentlyContinue) {\n");
        output.push_str("    Register-ArgumentCompleter -CommandName z -ScriptBlock __zoxide_z_complete\n");
        output.push_str("    Register-ArgumentCompleter -CommandName zi -ScriptBlock __zoxide_z_complete\n");
        output.push_str("}\n\n");

        output.push_str("function __zoxide_z_complete {\n");
        output.push_str("    $result = & zoxide query --exclude \"$(__zoxide_pwd)\" -- $args\n");
        output.push_str("    $result | ForEach-Object { $_ }\n");
        output.push_str("}\n\n");
    }

    output.push_str("# =============================================================================\n#\n");
    output.push_str("# To initialize zoxide, add this to your shell configuration file (usually $PROFILE):\n#\n");
    output.push_str("# eval \"$(zoxide init powershell)\"\n");

    println!("{}", output);
