    output.push_str("# cd + custom logic based on the value of _ZO_ECHO.\n");
    output.push_str("alias __zoxide_cd 'cd $argv'\n\n");

    output.push_str("# =============================================================================\n#\n");
    output.push_str("# Hook configuration for zoxide.\n#\n\n");

    output.push_str("# Hook to add new entries to the database.\n");
    output.push_str("set __zoxide_oldpwd = `__zoxide_pwd\n\n");
    output.push_str("alias __zoxide_hook 'if ( `__zoxide_pwd != $__zoxide_oldpwd ) { set __zoxide_oldpwd = `__zoxide_pwd; zoxide add -- $__zoxide_oldpwd }'\n\n");

    output.push_str("# Initialize hook.\n");
    output.push_str("if ( ! ( $preexec[1] == \"__zoxide_hook\" ) ) {\n");
