fn init_xonsh() {
    let mut output = String::new();

    output.push_str("# =============================================================================\n#\n");
    output.push_str("# Utility functions for zoxide.\n#\n\n");

    output.push_str("# pwd based on the value of _ZO_RESOLVE_SYMLINKS.\n");
    output.push_str("def __zoxide_pwd():\n");
    output.push_str("    return os.getcwd()\n");
    output.push_str("end\n\n");

    output.push_str("# cd + custom logic based on the value of _ZO_ECHO.\n");
    output.push_str("def __zoxide_cd(*args):\n");
    output.push_str("    os.chdir(*args)\n");
    output.push_str("end\n\n");

    output.push_str("# =============================================================================\n#\n");
    output.push_str("# Hook configuration for zoxide.\n#\n\n");

    output.push_str("# Hook to add new entries to the database.\n");
    output.push_str("__zoxide_oldpwd = __zoxide_pwd()\n\n");
    output.push_str("def __zoxide_hook():\n");
    output.push_str("    retval = $?\n");
    output.push_str("    pwd_tmp = __zoxide_pwd()\n");
    output.push_str("    if __zoxide_oldpwd != pwd_tmp:\n");
    output.push_str("        __zoxide_oldpwd = pwd_tmp\n");
    output.push_str("        zoxide add -- $__zoxide_oldpwd\n");
    output.push_str("    return retval\n");
    output.push_str("end\n\n");

    output.push_str("# Initialize hook.\n");
    output.push_str("if '__zoxide_hook' not in $env.ON_EXIT:\n");
    output.push_str("    $env.ON_EXIT.append(__zoxide_hook)\n");
    output.push_str("end\n\n");

    output.push_str("# Report common issues.\n");
    output.push_str("def __zoxide_doctor():\n");
    output.push_str("    if $env._ZO_DOCTOR == 0:\n");
    output.push_str("        return 0\n");
    output.push_str("    if '__zoxide_hook' in $env.ON_EXIT:\n");
    output.push_str("        return 0\n");
    output.push_str("    $env._ZO_DOCTOR = 0\n");
    output.push_str("    print('zoxide: detected a possible configuration issue.', file=__stderr__)\n");
    output.push_str("    print('Please ensure that zoxide is initialized right at the end of your shell configuration file.', file=__stderr__)\n");
    output.push_str("    print('', file=__stderr__)\n");
    output.push_str("    print('If the issue persists, consider filing an issue at:', file=__stderr__)\n");
    output.push_str("    print('https://github.com/ajeetdsouza/zoxide/issues', file=__stderr__)\n");
    output.push_str("    print('', file=__stderr__)\n");
    output.push_str("    print('Disable this message by setting _ZO_DOCTOR=0.', file=__stderr__)\n");
    output.push_str("end\n\n");

    output.push_str("# =============================================================================\n#\n");
    output.push_str("# When using zoxide with --no-cmd, alias these internal functions as desired.\n#\n\n");

    output.push_str("__zoxide_z_prefix = 'z#'\n\n");

    output.push_str("# Jump to a directory using only keywords.\n");
    output.push_str("def __zoxide_z(*args):\n");
    output.push_str("    __zoxide_doctor()\n");
    output.push_str("    if len(args) == 0:\n");
    output.push_str("        __zoxide_cd('~')\n");
    output.push_str("    elif len(args) == 1 and args[0] == '-':\n");
    output.push_str("        __zoxide_cd('$env.OLDPWD')\n");
    output.push_str("    elif len(args) == 1 and os.path.isdir(args[0]):\n");
    output.push_str("        __zoxide_cd(args[0])\n");
    output.push_str("    elif len(args) == 2 and args[0] == '--':\n");
    output.push_str("        __zoxide_cd(args[1])\n");
    output.push_str("    elif args[-1].startswith(__zoxide_z_prefix):\n");
    output.push_str("        result = args[-1]\n");
    output.push_str("        __zoxide_cd(result[len(__zoxide_z_prefix):])\n");
    output.push_str("    else:\n");
    output.push_str("        result = zoxide.query(exclude=__zoxide_pwd(), args=args)\n");
    output.push_str("        __zoxide_cd(result)\n");
    output.push_str("end\n\n");

    output.push_str("# Jump to a directory using interactive search.\n");
    output.push_str("def __zoxide_zi(*args):\n");
    output.push_str("    __zoxide_doctor()\n");
    output.push_str("    result = zoxide.query(interactive=True, args=args)\n");
    output.push_str("    __zoxide_cd(result)\n");
    output.push_str("end\n\n");

    output.push_str("# =============================================================================\n#\n");
    output.push_str("# Commands for zoxide. Disable these using --no-cmd.\n#\n\n");

    if no_cmd {
        output.push_str("# -- not configured --\n\n");
    } else {
        output.push_str("z = __zoxide_z\n");
        output.push_str("zi = __zoxide_zi\n\n");

        output.push_str("# Load completions.\n");
        output.push_str("def __zoxide_z_complete(args, line, complete):\n");
        output.push_str("    result = zoxide.query(exclude=__zoxide_pwd(), args=args)\n");
        output.push_str("    complete(result)\n");
    output.push_str("end\n\n");
    }

    output.push_str("# =============================================================================\n#\n");
    output.push_str("# To initialize zoxide, add this to your shell configuration file (usually ~/.xonshrc):\n#\n");
    output.push_str("# eval \"$(zoxide init xonsh)\"\n");

    println!("{}", output);
}
